const input = $input.first().json;
const text = input.body?.text ?? input.text ?? "";
const now = new Date();
const parts = Object.fromEntries(new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Taipei", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23" }).formatToParts(now).filter(p => p.type !== "literal").map(p => [p.type, p.value]));
const created_at = parts.year + "-" + parts.month + "-" + parts.day + "T" + parts.hour + ":" + parts.minute + ":" + parts.second + "+08:00";
const filename = "idea_" + parts.year + "-" + parts.month + "-" + parts.day + "_" + parts.hour + "-" + parts.minute + "-" + parts.second + ".json";
const document = { text, created_at, source: "LINE", project: "菲比 LINE 智能助理_02", version: "V2.0" };
const binary = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(document, null, 2), "utf8"), filename, "application/json");
return [{ json: document, binary: { data: binary } }];
